const customerLookupSchema = {
  type: 'object',
  properties: {
    customer_id: { type: 'string' },
  },
  required: ['customer_id'],
  additionalProperties: false,
};

export async function listTools() {
  return [
    {
      name: 'customer_lookup',
      description: 'Look up a customer by their customer_id and return their details.',
      inputSchema: customerLookupSchema,
    },
  ];
}

function validateArguments(args, schema) {
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  for (const key of Object.keys(args)) {
    if (!(key in schema.properties)) {
      throw new Error(`Invalid arguments: unexpected property '${key}'`);
    }
  }
  for (const field of schema.required) {
    if (!(field in args)) {
      throw new Error(`Invalid arguments: missing required property '${field}'`);
    }
  }
  for (const [key, def] of Object.entries(schema.properties)) {
    if (key in args) {
      const value = args[key];
      if (def.type === 'string' && typeof value !== 'string') {
        throw new Error(`Invalid arguments: '${key}' must be a string`);
      }
    }
  }
}

export async function callTool(name, args) {
  if (name !== 'customer_lookup') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const schema = customerLookupSchema;
  validateArguments(args, schema);

  const { customer_id } = args;
  const customer = customers[customer_id];
  if (!customer) {
    throw new Error(`Unknown customer: ${customer_id}`);
  }

  return {
    content: [
      {
        type: 'text',
        text: `Customer ${customer.name} (id: ${customer_id}, tier: ${customer.tier})`,
      },
    ],
  };
}
